	/**
	 * The loader compresses two disjoint sets of intermediate files, and the two deserve different settings: the
	 * write-once run files are on the hot path, while the staged inputs get re-read and are worth shrinking harder.
	 */
	@Test
	void perTierFlagsSelectACodecForEachTier() throws Exception {
		Path input = temporaryDirectory.resolve("input.nt");
		Files.writeString(input, "<urn:subject> <urn:predicate> <urn:object> .\n");

		ByteArrayOutputStream standardOutput = new ByteArrayOutputStream();
		ByteArrayOutputStream standardError = new ByteArrayOutputStream();
		int exitCode = LmdbBulkLoad.run(new String[] {
				"--store", temporaryDirectory.resolve("store").toString(),
				"--input", input.toString(),
				"--compression-runs", "fast",
				"--compression-staged", "17",
				"--progress", "none"
		}, new ByteArrayInputStream(new byte[0]), new PrintStream(standardOutput), new PrintStream(standardError));

		assertThat(exitCode)
				.as(standardError.toString(StandardCharsets.UTF_8))
				.isZero();
		assertThat(standardOutput.toString(StandardCharsets.UTF_8))
				.contains("stored=1")
				// runs=fast is the base, so the printed token names only the staged group that differs from it.
				.contains("compression=staged=17");
	}

