	/**
	 * Twenty artifacts is too many to answer on one line, so the interactive setup takes {@code custom} and then walks
	 * them one at a time with each artifact's current codec as the default.
	 */
	@Test
	void interactiveCustomCompressionWalksEveryArtifact() throws Exception {
		Path input = temporaryDirectory.resolve("input.nt");
		Files.writeString(input, "<urn:subject> <urn:predicate> <urn:object> .\n");
		Path store = temporaryDirectory.resolve("store");
		// Ten leading prompts, then custom, then one answer per artifact, then the remaining prompts. Every artifact is
		// accepted at its default except id-quads, which is turned off to prove the walk's answers are kept.
		List<String> answers = new ArrayList<>(List.of("", "", "", "", "", "", "", "", "", "", "custom"));
		for (BulkArtifact artifact : BulkArtifact.values()) {
			answers.add(artifact == BulkArtifact.ID_QUADS ? "none" : "");
		}
		answers.addAll(List.of("none", "", "", "", "", "", "", ""));
		ByteArrayOutputStream standardOutput = new ByteArrayOutputStream();
		ByteArrayOutputStream standardError = new ByteArrayOutputStream();

		int exitCode = LmdbBulkLoad.run(new String[] {
				"--interactive",
				"--store", store.toString(),
				"--input", input.toString()
		}, new ByteArrayInputStream((String.join("\n", answers) + "\n").getBytes(StandardCharsets.UTF_8)),
				new PrintStream(standardOutput), new PrintStream(standardError));

		assertThat(exitCode)
				.as(standardError.toString(StandardCharsets.UTF_8))
				.isZero();
		String prompts = standardError.toString(StandardCharsets.UTF_8);
		for (BulkArtifact artifact : BulkArtifact.values()) {
			assertThat(prompts).as("the walk must prompt for %s", artifact.key()).contains(artifact.key());
		}
		assertThat(standardOutput.toString(StandardCharsets.UTF_8)).contains("compression=id-quads=none");
	}

